<script setup>
import {ref,onMounted,watch} from 'vue'
import {customer,customerRequest,refreshCustomer,acceptCustomer,logoutCustomer} from './customerApi.js'
import {trackingLink} from '../../../shared/fulfillment.js'
import {orderStatuses} from '../../../shared/commerce.js'
const props=defineProps({repeatOrder:Function,locked:Boolean})
const available=ref(false),email=ref(''),code=ref(''),challenge=ref(null),busy=ref(false),error=ref(''),notice=ref(''),profile=ref(null),addresses=ref([]),address=ref(null),orders=ref([]),detail=ref(null),proposal=ref(null),page=ref(1),more=ref(false),resendAt=ref(0),retrySeconds=ref(0)
const money=n=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB'}).format(n/100)
const date=value=>new Date(value).toLocaleString('ru')
const payment={unpaid:'Не оплачено',pending:'Ожидает подтверждения',paid:'Оплачено',refunded:'Возврат подтверждён'}
let interval,generation=0
async function loadOrders(){const owner=customer.user?.id;const r=await customerRequest('/api/account/orders?page='+page.value);if(owner!==customer.user?.id)return;orders.value=r.items;more.value=r.has_more}
async function load(){const version=++generation;if(!customer.user)return;profile.value={name:customer.user.name,phone:customer.user.phone,revision:customer.user.revision};const [a,o]=await Promise.all([customerRequest('/api/account/addresses'),customerRequest('/api/account/orders?page='+page.value)]);if(version!==generation||!customer.user)return;addresses.value=a;orders.value=o.items;more.value=o.has_more}
async function work(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function requestCode(){await work(async()=>{challenge.value=await customerRequest('/api/account/login/request','POST',{email:email.value});code.value='';resendAt.value=Date.now()+challenge.value.resend_after*1000;retrySeconds.value=challenge.value.resend_after;notice.value='Код отправлен на '+email.value+'. Проверьте входящие и папку «Спам». Он действует 10 минут.'})}
async function verify(){await work(async()=>{const data=await customerRequest('/api/account/login/verify','POST',{challenge_id:challenge.value.challenge_id,code:code.value});acceptCustomer(data);challenge.value=null;code.value='';page.value=1;await load()})}
async function logout(all){await work(async()=>{await logoutCustomer(all);notice.value='Вы вышли из личного кабинета.'})}
async function saveProfile(){await work(async()=>{const owner=customer.user?.id;const value=await customerRequest('/api/account/profile','PUT',profile.value);if(owner!==customer.user?.id)return;customer.user=value;profile.value={name:customer.user.name,phone:customer.user.phone,revision:customer.user.revision};notice.value='Профиль сохранён.'})}
function editAddress(row){address.value=row?{...row}:{label:'',name:customer.user.name,phone:customer.user.phone,address:'',is_default:!addresses.value.length}}
async function saveAddress(){await work(async()=>{const {id,...body}=address.value;await customerRequest('/api/account/addresses'+(id?'/'+id:''),id?'PUT':'POST',body);address.value=null;await load();notice.value='Адрес сохранён.'})}
async function removeAddress(row){if(!confirm('Удалить сохранённый адрес «'+row.label+'»?'))return;await work(async()=>{await customerRequest('/api/account/addresses/'+row.id,'DELETE',{revision:row.revision});await load()})}
async function inspect(row){await work(async()=>{const owner=customer.user?.id;const value=await customerRequest('/api/account/orders/'+row.id);if(owner===customer.user?.id)detail.value=value})}
async function repeat(){await work(async()=>{const owner=customer.user?.id;const value=await customerRequest('/api/account/orders/'+detail.value.id+'/reorder','POST',{});if(owner===customer.user?.id)proposal.value=value})}
async function addRepeat(){await work(async()=>{if(props.locked)throw Error('Завершите текущее оформление заказа');await props.repeatOrder(proposal.value.items);proposal.value=null;detail.value=null})}
watch(()=>customer.user?.id,(id,previous)=>{generation++;profile.value=null;addresses.value=[];orders.value=[];address.value=null;detail.value=null;proposal.value=null;page.value=1;if(id&&previous!==undefined)load().catch(e=>error.value=e.message)},{flush:'sync'})
onMounted(async()=>{try{available.value=(await customerRequest('/api/account/config')).available;await refreshCustomer();await load()}catch(e){error.value=e.message}interval=setInterval(()=>{retrySeconds.value=Math.max(0,Math.ceil((resendAt.value-Date.now())/1000))},1000)})
import {onBeforeUnmount} from 'vue'
onBeforeUnmount(()=>{generation++;clearInterval(interval)})
</script>
<template>
 <main class="container customer-account"><div class="account-heading"><div><span class="section-kicker">ПОКУПАТЕЛЮ</span><h1>Личный кабинет</h1></div><div v-if="customer.user"><button class="account-button" :disabled="busy" @click="logout(false)">Выйти из кабинета</button><button class="account-button" :disabled="busy" @click="logout(true)">Выйти на всех устройствах</button></div></div><p v-if="error" class="account-error" role="alert">{{error}}</p><p v-if="notice" class="account-notice" role="status">{{notice}}</p>
 <section v-if="!customer.user" class="account-panel login-panel"><h2>Вход по email</h2><p>Введите почту — отправим одноразовый код. При первом входе кабинет создаётся автоматически.</p><p v-if="!available">Вход по email пока не настроен магазином. Заказ можно оформить без личного кабинета.</p><form @submit.prevent="requestCode"><label>Электронная почта<input v-model="email" type="email" maxlength="254" autocomplete="email" :disabled="busy||!!challenge" required></label><button class="primary-button" :disabled="busy||!available||!!challenge">Получить код входа</button></form><form v-if="challenge" @submit.prevent="verify"><label>Код из письма<input v-model="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" minlength="6" maxlength="6" :disabled="busy" required></label><button class="primary-button" :disabled="busy">Войти в кабинет</button><button type="button" class="account-button" :disabled="busy||retrySeconds>0" @click="requestCode">{{retrySeconds?'Повторить через '+retrySeconds+' с':'Отправить код повторно'}}</button><button type="button" class="account-button" :disabled="busy" @click="challenge=null;code='';notice=''">Изменить email</button></form><p class="account-help">История доступна для заказов, оформленных после входа в эту учётную запись. Гостевые заказы не привязываются по совпадению телефона или email.</p></section>
 <template v-else><p class="verified-email">Вход выполнен: {{customer.user.email}}</p><div class="account-columns"><section class="account-panel"><h2>Профиль</h2><form v-if="profile" @submit.prevent="saveProfile"><label>Ваше имя<input v-model="profile.name" autocomplete="name" maxlength="150" :disabled="busy"></label><label>Ваш телефон<input v-model="profile.phone" type="tel" autocomplete="tel" maxlength="40" :disabled="busy"></label><button class="primary-button" :disabled="busy">Сохранить профиль</button></form></section><section class="account-panel"><div class="account-heading"><h2>Сохранённые адреса</h2><button class="account-button" :disabled="busy||addresses.length>=20" @click="editAddress()">Добавить адрес</button></div><p v-if="!addresses.length">Адресов пока нет. Сохраните адрес, чтобы выбирать его при оформлении.</p><article v-for="a in addresses" :key="a.id" class="address-card"><strong>{{a.label}} <small v-if="a.is_default">· По умолчанию</small></strong><p>{{a.name}} · {{a.phone}}</p><p class="address-text">{{a.address}}</p><button class="account-button" :disabled="busy" @click="editAddress(a)">Изменить адрес</button><button class="account-button" :disabled="busy" @click="removeAddress(a)">Удалить адрес</button></article></section></div>
 <section class="account-panel"><div class="account-heading"><h2>Мои заказы</h2><button class="account-button" :disabled="busy" @click="work(loadOrders)">Обновить историю</button></div><p v-if="!orders.length">Заказов пока нет. После входа оформленные заказы появятся здесь.</p><div class="account-table"><table v-if="orders.length"><thead><tr><th>Заказ</th><th>Дата</th><th>Статус</th><th>Сумма</th><th></th></tr></thead><tbody><tr v-for="o in orders" :key="o.id"><td>{{o.number}}</td><td>{{date(o.created_at)}}</td><td>{{orderStatuses[o.status]}}<small>{{payment[o.payment_state]||'Оплата не подтверждена'}}</small></td><td>{{money(o.total_cents)}}</td><td><button class="account-button" :disabled="busy" @click="inspect(o)">Открыть заказ</button></td></tr></tbody></table></div><div class="account-pagination"><button v-if="page>1" class="account-button" :disabled="busy" @click="page--;work(loadOrders)">Предыдущие заказы</button><button v-if="more" class="account-button" :disabled="busy" @click="page++;work(loadOrders)">Следующие заказы</button></div></section></template>
 <div v-if="customer.user&&address" class="account-backdrop"><section class="account-dialog" role="dialog" aria-modal="true" aria-label="Сохранённый адрес"><div class="account-heading"><h2>{{address.id?'Изменить адрес':'Новый адрес'}}</h2><button class="account-button" :disabled="busy" aria-label="Закрыть адрес" @click="address=null">×</button></div><form @submit.prevent="saveAddress"><fieldset :disabled="busy"><label>Название адреса<input v-model="address.label" placeholder="Например, дом" maxlength="80" required></label><label>Получатель<input v-model="address.name" autocomplete="name" maxlength="150" required></label><label>Телефон получателя<input v-model="address.phone" type="tel" autocomplete="tel" maxlength="40" required></label><label>Адрес доставки<textarea v-model="address.address" autocomplete="street-address" maxlength="1000" rows="4" required></textarea></label><label class="account-check"><input v-model="address.is_default" type="checkbox"> Использовать по умолчанию</label></fieldset><p v-if="error" class="account-error" role="alert">{{error}}</p><button class="primary-button" :disabled="busy">Сохранить адрес</button></form></section></div>
 <div v-if="customer.user&&detail" class="account-backdrop"><section class="account-dialog order-dialog" role="dialog" aria-modal="true" aria-label="Мой заказ"><div class="account-heading"><h2>Заказ {{detail.number}}</h2><button class="account-button" :disabled="busy" aria-label="Закрыть заказ" @click="detail=null;proposal=null">×</button></div><p>{{date(detail.created_at)}} · {{orderStatuses[detail.status]}} · {{payment[detail.payment_state]||'Оплата не подтверждена'}}</p><article v-for="(item,i) in detail.items" :key="i" class="order-line"><strong>{{item.name}}{{item.variant_name?' — '+item.variant_name:''}}</strong><span>{{item.quantity}} × {{money(item.unit_cents)}}</span></article><p>Получатель: {{detail.customer_name}} · {{detail.phone}}</p><p class="address-text">{{detail.delivery_snapshot.title||detail.delivery_method}}{{detail.address?' · '+detail.address:''}}</p><p v-if="detail.comment" class="address-text">Комментарий: {{detail.comment}}</p><p v-if="detail.tracking_code">Трек-номер: {{detail.tracking_code}}</p><a v-if="detail.tracking_url&&trackingLink(detail.tracking_url)" :href="detail.tracking_url" target="_blank" rel="noopener noreferrer">Отследить доставку</a><p>Доставка: {{money(detail.delivery_cents)}} · <strong>Итого: {{money(detail.total_cents)}}</strong></p><details><summary>История статусов</summary><p v-for="(event,i) in detail.history" :key="i">{{date(event.created_at)}} · {{orderStatuses[event.status]}}</p></details><p v-if="error" class="account-error" role="alert">{{error}}</p><button class="primary-button" :disabled="busy||locked" @click="repeat">Повторить заказ</button><section v-if="proposal" class="repeat-preview" aria-label="Повтор заказа"><h3>Проверьте повтор заказа</h3><p>Текущие цены и остатки проверены. Доставка рассчитывается при новом оформлении.</p><p v-for="(warning,i) in proposal.warnings" :key="i" class="account-notice">{{warning}}</p><article v-for="item in proposal.items" :key="item.product_id+item.variant_name" class="order-line"><strong>{{item.name}}{{item.variant_name?' — '+item.variant_name:''}}</strong><span>{{item.quantity}} × {{money(item.unit_cents)}}<small v-if="item.unit_cents!==item.previous_unit_cents">Раньше: {{money(item.previous_unit_cents)}}</small></span></article><p v-if="!proposal.items.length">Все товары этого заказа сейчас недоступны.</p><p v-else>Товары: {{money(proposal.total_cents)}}</p><button class="primary-button" :disabled="busy||locked||!proposal.items.length" @click="addRepeat">Добавить повтор в корзину</button></section></section></div>
 </main>
</template>
<style scoped>
.customer-account{padding-top:40px;padding-bottom:70px;min-height:65vh;overflow-wrap:anywhere}.account-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.customer-account h1{font-size:32px;margin:10px 0 22px}.customer-account h2{font-size:21px;margin:0 0 16px}.account-columns{display:grid;grid-template-columns:1fr 1.3fr;gap:24px}.account-panel{padding:24px;border:1px solid #d8e4dc;border-radius:var(--nova-radius);margin:22px 0;background:var(--nova-background)}.login-panel{max-width:620px}.customer-account form{display:grid;gap:16px;margin-top:18px}.customer-account label{display:grid;gap:8px;font-size:14px}.customer-account input,.customer-account textarea{min-width:0;width:100%;box-sizing:border-box;background:var(--nova-background);color:inherit;border:1px solid #cbd8cf;border-radius:6px;padding:12px;font:inherit}.customer-account fieldset{border:0;padding:0;margin:0;display:grid;gap:16px;min-width:0}.account-check{display:flex!important;align-items:center}.account-check input{width:auto}.account-button{border:1px solid #cbd8cf;border-radius:6px;padding:9px 12px;background:var(--nova-background);color:var(--nova-primary);cursor:pointer;font:inherit;font-size:13px;margin:3px}.customer-account p{line-height:1.65;font-size:14px}.account-error{background:#fff0ed;color:#962b27;padding:14px}.account-notice{background:#eff8f1;color:#285e40;padding:14px}.account-help{opacity:.75}.account-table{overflow:auto}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid #d8e4dc;font-size:13px;white-space:nowrap}small{display:block;font-size:12px;opacity:.75;margin-top:5px}.address-card{border-top:1px solid #d8e4dc;padding:16px 0}.address-text{white-space:pre-wrap}.address-card small{display:inline}.account-backdrop{position:fixed;inset:0;background:#142b2b88;z-index:80;display:flex;align-items:center;justify-content:center;padding:16px}.account-dialog{background:var(--nova-background,#fff);color:var(--nova-text,#202d33);border-radius:var(--nova-radius);width:min(650px,100%);max-height:90vh;overflow:auto;padding:24px;box-sizing:border-box}.order-dialog{width:min(800px,100%)}.order-line{display:flex;justify-content:space-between;gap:16px;padding:14px 0;border-bottom:1px solid #d8e4dc}.repeat-preview{border:1px solid #d8e4dc;padding:18px;margin-top:20px;border-radius:8px}.account-dialog>.primary-button{margin:18px 0}summary{cursor:pointer}.customer-account button:disabled{opacity:.5;cursor:default}@media(max-width:700px){.account-columns{grid-template-columns:1fr;gap:0}.account-panel{padding:18px}.account-dialog{padding:18px}.order-line{flex-wrap:wrap}.customer-account h1{font-size:27px}}
</style>
